// spec: specs/delivery.md §15 · кейс .qa/tests/delivery/dlv-19-print-header-meta-alignment.md · seed: tests/seed.admin.spec.ts
// #35cb11 (עבר QA 19.11): блок .pd-meta в шапке печатных документов (общий класс) — строки начинаются на одной линии:
//   правые края текста 4 строк (תעודת משלוח #504: «ת. משלוח DN-504», «הזמנה #504», «תאריך הזמנה», «שעת הזמנה») равны ±1px
//   (было x=179/152/214/181 — разброс 62px), блок остаётся СЛЕВА шапки. То же — קבלה #685, דוח לרואה חשבון, печать доски /delivery.
// Замер: Range по содержимому каждой строки (текст, а не блочный бокс — иначе выравнивание влево не поймать) при emulateMedia print.
// Только чтение, ничего не создаёт → @prod-safe.
import { test, expect, Page } from '@playwright/test';
import * as path from 'path';

test.use({ storageState: path.resolve(__dirname, '../../../auth/admin.json') });

const DN504 = '/delivery/6f797bf5-1ef8-44eb-8ad5-073e0b0f341e';
const RECEIPT685 = '/orders/a6f2f8c0-6d4d-4a8b-a03f-44f041778a3d/receipt';
const TOL = 1;

const today = () => new Intl.DateTimeFormat('en-CA', { timeZone: 'Asia/Jerusalem' }).format(new Date()); // YYYY-MM-DD

/** Строки блока .pd-meta в шапке печати: текст и правый/левый край текста. */
const metaLines = (page: Page) => page.evaluate(() => {
  const strip = (s: string) => s.replace(/[‎‏‪-‮⁦-⁩]/g, '').replace(/\s+/g, ' ').trim();
  const meta = [...document.querySelectorAll('.pd-head .pd-meta')].find((m) => (m as HTMLElement).checkVisibility())!;
  const mr = meta.getBoundingClientRect();
  const lines = [...meta.children].map((c) => {
    const range = document.createRange();
    range.selectNodeContents(c);
    const r = range.getBoundingClientRect();
    return { text: strip(c.textContent || ''), right: r.right, left: r.left, top: r.top };
  });
  const title = document.querySelector('.pd-head .pd-title')!.getBoundingClientRect();
  return { lines, metaCx: mr.left + mr.width / 2, vw: innerWidth, titleLeft: title.left, metaRight: mr.right };
});

async function expectAligned(page: Page, expectTexts: (string | RegExp)[]) {
  const m = await metaLines(page);
  expect(m.lines.map((l) => l.text).length, 'число строк в блоке').toBe(expectTexts.length);
  expectTexts.forEach((t, i) => (typeof t === 'string' ? expect(m.lines[i].text).toBe(t) : expect(m.lines[i].text).toMatch(t)));
  const rights = m.lines.map((l) => Math.round(l.right * 10) / 10);
  const spread = Math.max(...rights) - Math.min(...rights);
  expect(spread, `правые края строк блока: ${rights.join(' / ')} (разброс ≤ ${TOL}px)`).toBeLessThanOrEqual(TOL);
  const tops = m.lines.map((l) => l.top);
  expect(tops, 'строки идут столбиком (каждая ниже предыдущей)').toEqual([...tops].sort((a, b) => a - b));
  expect(new Set(tops.map((t) => Math.round(t))).size, 'строки на разных высотах').toBe(tops.length);
  expect(m.metaCx, 'блок остаётся слева шапки').toBeLessThan(m.vw / 2);
  expect(m.metaRight, 'блок слева от заголовка документа').toBeLessThanOrEqual(m.titleLeft + 1);
}

async function print(page: Page) {
  await page.emulateMedia({ media: 'print' });
}

test.describe('печать: блок .pd-meta в шапке выровнен по правому краю (#35cb11)', () => {
  test('תעודת משלוח #504: 4 שורות מתחילות באותו קו (±1px), הבלוק משמאל #35cb11 @desktop @prod-safe', async ({ page }) => {
    await page.goto(DN504);
    await expect(page.getByRole('heading', { level: 1, name: 'תעודת משלוח · הזמנה #504' })).toBeVisible({ timeout: 30_000 });
    await print(page);
    await expect(page.locator('.pd-head .pd-meta')).toBeVisible();
    await expectAligned(page, ['ת. משלוח DN-504', 'הזמנה #504', 'תאריך הזמנה: 04.10.2026', 'שעת הזמנה: 15:21']);
  });

  test('קבלה #685 (מסך ← הדפסה): שלוש שורות הבלוק מיושרות, הבלוק משמאל #35cb11 @desktop @prod-safe', async ({ page }) => {
    await page.goto(RECEIPT685);
    await expect(page.getByRole('heading', { level: 1, name: 'קבלה #2 · הזמנה #685' })).toBeVisible({ timeout: 30_000 });
    await print(page);
    await expect(page.locator('.pd-head .pd-meta')).toBeVisible();
    await expectAligned(page, ['קבלה #2', 'הזמנה #685', /^תאריך הפקה: \d{2}\.\d{2}\.\d{4}, \d{2}:\d{2}$/]);
  });

  test('דוח לרואה חשבון: «לתקופה», «הופק», «שיעור מע"מ» מיושרות, הבלוק משמאל #35cb11 @desktop @prod-safe', async ({ page }) => {
    await page.goto(`/reports/accounting?from=2026-10-01&to=${today()}`);
    await expect(page.locator('.pd-head .pd-title')).toHaveText('דוח לרואה חשבון', { timeout: 30_000 });
    await print(page);
    await expect(page.locator('.pd-head .pd-meta')).toBeVisible();
    await expectAligned(page, [/^לתקופה: \d{2}\.\d{2}\.\d{4} – \d{2}\.\d{2}\.\d{4}$/, /^הופק: /, /^שיעור מע["״]מ: \d+%$/]);
  });

  test('לוח משלוחים (הדפסת «דוח משלוחים»): «הופק», «נהג», סינון מיושרים, הבלוק משמאל #35cb11 @desktop @prod-safe', async ({ page }) => {
    await page.goto('/delivery');
    await expect(page.getByRole('heading', { level: 1, name: 'משלוחים' })).toBeVisible({ timeout: 30_000 });
    await expect(page.locator('.pd-head .pd-title')).toHaveText('דוח משלוחים', { timeout: 30_000 });
    await print(page);
    await expect(page.locator('.pd-head .pd-meta')).toBeVisible();
    await expectAligned(page, [/^הופק: /, /^נהג: /, /.+/]);
  });
});
